CREATE OR REPLACE FUNCTION public.can_manage_course(_course uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_platform_admin() OR EXISTS(SELECT 1 FROM public.courses c JOIN public.institutions i ON i.id=c.institution_id WHERE c.id=_course AND i.status='active' AND (public.can_access_institution(c.institution_id,true) OR (c.instructor_id=auth.uid() AND EXISTS(SELECT 1 FROM public.institution_memberships m WHERE m.user_id=auth.uid() AND m.institution_id=c.institution_id AND m.role='teacher' AND m.active)))); $$;
CREATE OR REPLACE FUNCTION public.can_learn_course(_course uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_manage_course(_course) OR EXISTS(SELECT 1 FROM public.courses c JOIN public.institutions i ON i.id=c.institution_id JOIN public.enrollments e ON e.course_id=c.id WHERE c.id=_course AND i.status='active' AND c.is_published AND e.user_id=auth.uid() AND e.status IN ('active','completed')); $$;
CREATE OR REPLACE FUNCTION public.lesson_course(_lesson uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.course_id FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE l.id=_lesson; $$;
CREATE OR REPLACE FUNCTION public.quiz_course(_quiz uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT course_id FROM public.quizzes WHERE id=_quiz; $$;
CREATE OR REPLACE FUNCTION public.question_course(_question uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT q.course_id FROM public.quiz_questions x JOIN public.quizzes q ON q.id=x.quiz_id WHERE x.id=_question; $$;
CREATE OR REPLACE FUNCTION public.assignment_course(_assignment uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT course_id FROM public.assignments WHERE id=_assignment; $$;
REVOKE ALL ON FUNCTION public.can_manage_course(uuid),public.can_learn_course(uuid),public.lesson_course(uuid),public.quiz_course(uuid),public.question_course(uuid),public.assignment_course(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_course(uuid),public.can_learn_course(uuid),public.lesson_course(uuid),public.quiz_course(uuid),public.question_course(uuid),public.assignment_course(uuid) TO authenticated,service_role;
DROP POLICY "Course view" ON public.courses;
DROP POLICY "Course manage" ON public.courses;
CREATE POLICY "Published session discovery" ON public.courses FOR SELECT TO authenticated USING(public.can_manage_course(id) OR (is_published AND EXISTS(SELECT 1 FROM public.institutions i WHERE i.id=institution_id AND i.status='active')));
CREATE POLICY "Course edits" ON public.courses FOR UPDATE TO authenticated USING(public.can_manage_course(id)) WITH CHECK(public.can_manage_course(id));
CREATE POLICY "Course deletes" ON public.courses FOR DELETE TO authenticated USING(public.can_manage_course(id));
CREATE POLICY "Company session creation" ON public.courses FOR INSERT TO authenticated WITH CHECK(public.can_access_institution(institution_id,true) AND instructor_id=auth.uid());
DROP POLICY "Module access" ON public.modules;
CREATE POLICY "Module read" ON public.modules FOR SELECT TO authenticated USING(public.can_learn_course(course_id));
CREATE POLICY "Module manage" ON public.modules FOR ALL TO authenticated USING(public.can_manage_course(course_id)) WITH CHECK(public.can_manage_course(course_id));
DROP POLICY "Lesson access" ON public.lessons;
CREATE POLICY "Lesson read" ON public.lessons FOR SELECT TO authenticated USING(public.can_learn_course(public.lesson_course(id)));
CREATE POLICY "Lesson manage" ON public.lessons FOR ALL TO authenticated USING(public.can_manage_course(public.lesson_course(id))) WITH CHECK(EXISTS(SELECT 1 FROM public.modules m WHERE m.id=module_id AND public.can_manage_course(m.course_id)));
DROP POLICY "Material access" ON public.learning_materials;
CREATE POLICY "Material read" ON public.learning_materials FOR SELECT TO authenticated USING(public.can_learn_course(public.lesson_course(lesson_id)));
CREATE POLICY "Material manage" ON public.learning_materials FOR ALL TO authenticated USING(public.can_manage_course(public.lesson_course(lesson_id))) WITH CHECK(public.can_manage_course(public.lesson_course(lesson_id)));
DROP POLICY "Lesson notes access" ON public.lesson_notes;
CREATE POLICY "Note read" ON public.lesson_notes FOR SELECT TO authenticated USING(public.can_learn_course(public.lesson_course(lesson_id)));
CREATE POLICY "Note manage" ON public.lesson_notes FOR ALL TO authenticated USING(public.can_manage_course(public.lesson_course(lesson_id))) WITH CHECK(author_id=auth.uid() AND public.can_manage_course(public.lesson_course(lesson_id)));
DROP POLICY "Enrollment insert" ON public.enrollments;
CREATE POLICY "Free enrollment only" ON public.enrollments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='active' AND payment_id IS NULL AND EXISTS(SELECT 1 FROM public.courses c JOIN public.institutions i ON i.id=c.institution_id WHERE c.id=course_id AND c.price=0 AND c.is_published AND i.status='active'));
DROP POLICY "Enrollment view" ON public.enrollments;
CREATE POLICY "Enrollment read" ON public.enrollments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage_course(course_id));
REVOKE INSERT,UPDATE,DELETE ON public.payments FROM authenticated;
DROP POLICY "Payment insert" ON public.payments;
DROP POLICY "Own progress" ON public.lesson_progress;
CREATE POLICY "Progress read" ON public.lesson_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage_course(public.lesson_course(lesson_id)));
CREATE POLICY "Progress write" ON public.lesson_progress FOR ALL TO authenticated USING(user_id=auth.uid() AND public.can_learn_course(public.lesson_course(lesson_id))) WITH CHECK(user_id=auth.uid() AND public.can_learn_course(public.lesson_course(lesson_id)));
DROP POLICY "Quiz access" ON public.quizzes;
CREATE POLICY "Quiz read" ON public.quizzes FOR SELECT TO authenticated USING(public.can_manage_course(course_id) OR (is_published AND public.can_learn_course(course_id)));
CREATE POLICY "Quiz manage" ON public.quizzes FOR ALL TO authenticated USING(public.can_manage_course(course_id)) WITH CHECK(public.can_manage_course(course_id));
DROP POLICY "Question access" ON public.quiz_questions;
CREATE POLICY "Question read" ON public.quiz_questions FOR SELECT TO authenticated USING(public.can_learn_course(public.quiz_course(quiz_id)));
CREATE POLICY "Question manage" ON public.quiz_questions FOR ALL TO authenticated USING(public.can_manage_course(public.quiz_course(quiz_id))) WITH CHECK(public.can_manage_course(public.quiz_course(quiz_id)));
DROP POLICY "Option access" ON public.quiz_question_options;
CREATE POLICY "Option read" ON public.quiz_question_options FOR SELECT TO authenticated USING(public.can_learn_course(public.question_course(question_id)));
CREATE POLICY "Option manage" ON public.quiz_question_options FOR ALL TO authenticated USING(public.can_manage_course(public.question_course(question_id))) WITH CHECK(public.can_manage_course(public.question_course(question_id)));
REVOKE SELECT ON public.quiz_question_options FROM authenticated;
GRANT SELECT(id,question_id,option_text,sort_order) ON public.quiz_question_options TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.quiz_attempts FROM authenticated;
DROP POLICY "Own attempts" ON public.quiz_attempts;
CREATE POLICY "Attempt read" ON public.quiz_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage_course(public.quiz_course(quiz_id)));
DROP POLICY "Assignment access" ON public.assignments;
CREATE POLICY "Assignment read" ON public.assignments FOR SELECT TO authenticated USING(public.can_learn_course(course_id));
CREATE POLICY "Assignment manage" ON public.assignments FOR ALL TO authenticated USING(public.can_manage_course(course_id)) WITH CHECK(public.can_manage_course(course_id));
DROP POLICY "Submission access" ON public.assignment_submissions;
CREATE POLICY "Submission read" ON public.assignment_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage_course(public.assignment_course(assignment_id)));
CREATE POLICY "Submission insert" ON public.assignment_submissions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND grade IS NULL AND graded_by IS NULL AND public.can_learn_course(public.assignment_course(assignment_id)));
CREATE POLICY "Submission update" ON public.assignment_submissions FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.can_manage_course(public.assignment_course(assignment_id))) WITH CHECK(user_id=auth.uid() OR public.can_manage_course(public.assignment_course(assignment_id)));
CREATE OR REPLACE FUNCTION public.protect_submission_grade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.can_manage_course(public.assignment_course(NEW.assignment_id)) AND (NEW.grade IS DISTINCT FROM OLD.grade OR NEW.feedback IS DISTINCT FROM OLD.feedback OR NEW.graded_by IS DISTINCT FROM OLD.graded_by OR NEW.graded_at IS DISTINCT FROM OLD.graded_at OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.assignment_id IS DISTINCT FROM OLD.assignment_id) THEN RAISE EXCEPTION 'Only assigned instructors can grade submissions'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_submission_grade BEFORE UPDATE ON public.assignment_submissions FOR EACH ROW EXECUTE FUNCTION public.protect_submission_grade();
CREATE POLICY "Company account contacts" ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.institution_memberships m WHERE m.user_id=id AND public.can_access_institution(m.institution_id,true)) OR EXISTS(SELECT 1 FROM public.enrollments e WHERE e.user_id=id AND public.can_manage_course(e.course_id)));
CREATE POLICY "Peer company names" ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.institution_memberships m WHERE m.user_id=id AND public.has_institution_membership(m.institution_id)));
DROP POLICY "Announcement access" ON public.announcements;
CREATE POLICY "Announcement read" ON public.announcements FOR SELECT TO authenticated USING(public.is_platform_admin() OR public.can_access_institution(institution_id,false));
CREATE POLICY "Announcement manage" ON public.announcements FOR ALL TO authenticated USING(public.can_access_institution(institution_id,true)) WITH CHECK(author_id=auth.uid() AND public.can_access_institution(institution_id,true));
DROP POLICY "Attendance session access" ON public.attendance_sessions;
CREATE POLICY "Attendance session read" ON public.attendance_sessions FOR SELECT TO authenticated USING(public.can_access_institution(institution_id,false));
CREATE POLICY "Attendance session manage" ON public.attendance_sessions FOR ALL TO authenticated USING(public.can_access_institution(institution_id,true) OR public.can_manage_course(course_id)) WITH CHECK(public.can_access_institution(institution_id,true) OR public.can_manage_course(course_id));
DROP POLICY "Attendance records access" ON public.attendance_records;
CREATE POLICY "Attendance record read" ON public.attendance_records FOR SELECT TO authenticated USING(student_id=auth.uid() OR EXISTS(SELECT 1 FROM public.attendance_sessions s WHERE s.id=session_id AND (public.can_access_institution(s.institution_id,true) OR public.can_manage_course(s.course_id))));
CREATE POLICY "Attendance record manage" ON public.attendance_records FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.attendance_sessions s WHERE s.id=session_id AND (public.can_access_institution(s.institution_id,true) OR public.can_manage_course(s.course_id)))) WITH CHECK(EXISTS(SELECT 1 FROM public.attendance_sessions s WHERE s.id=session_id AND (public.can_access_institution(s.institution_id,true) OR public.can_manage_course(s.course_id))));
DROP POLICY "Direct messages insert" ON public.direct_messages;
CREATE POLICY "Company messages insert" ON public.direct_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND (public.is_platform_admin() OR (institution_id IS NOT NULL AND public.has_institution_membership(institution_id) AND EXISTS(SELECT 1 FROM public.institution_memberships m WHERE m.institution_id=direct_messages.institution_id AND m.user_id=recipient_id AND m.active))));
CREATE OR REPLACE FUNCTION public.assign_institution_member(_institution_id uuid,_user_id uuid,_role public.app_role,_active boolean DEFAULT true) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result_id uuid; BEGIN IF NOT public.can_access_institution(_institution_id,true) THEN RAISE EXCEPTION 'Company administrator required'; END IF; IF _role='super_admin' THEN RAISE EXCEPTION 'Invalid company role'; END IF; IF NOT public.is_platform_admin() AND (NOT EXISTS(SELECT 1 FROM public.institution_memberships WHERE institution_id=_institution_id AND user_id=_user_id) OR _user_id=auth.uid() OR _role='institution_admin') THEN RAISE EXCEPTION 'Only platform administrators assign company administrators or external accounts'; END IF; INSERT INTO public.institution_memberships(institution_id,user_id,role,active) VALUES(_institution_id,_user_id,_role,_active) ON CONFLICT(institution_id,user_id) DO UPDATE SET role=EXCLUDED.role,active=EXCLUDED.active RETURNING id INTO result_id; RETURN result_id; END; $$;
DROP POLICY "Institution subscription access" ON public.institution_subscriptions;
CREATE POLICY "Subscription read" ON public.institution_subscriptions FOR SELECT TO authenticated USING(public.can_access_institution(institution_id,true));
CREATE POLICY "Subscription manage" ON public.institution_subscriptions FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());